result={'status':'CHECKPOINT A ACTUAL RESOURCE ACCOUNTING; NO TRANSITION BATCH','cameraCombinations':12,'posesPerCombination':24,'nativePngCount':288,'byteIdenticalReviewedPngReused':reused,'newActualPoseRenderCount':len(frames)-reused,'newTransitionRasterCount':0,'newPackedBlendCopies':0,'sourcePackedBlend':'../transitions/mpfb-start-stop-technical.blend (existing immutable source)','nativePngResolution':[384,384],'cyclesSamples':8,'denoising':True,'blenderInvocationThreads':2,'firstCheckpointImageUtc':utc(first),'lastCheckpointImageUtc':utc(last),'checkpointImageWallSpanSeconds':last-first,'cyclesReportedRenderWallSecondsTotal':sum(reported),'cyclesReportedLongestRenderWallSeconds':max(reported),'cyclesReportedOther263RenderWallSeconds':sum(reported)-max(reported),'cpuUtilizationMeasured':False,'wallTimeNote':'One native frame reports a4h18m wall-clock interval; cause is not inferred. Other263 render intervals total approximately18m09s. Wall-clock observations do not establish CPU occupancy.','nativePngBytes':sum(p.stat().st_size for p in png),'artifactBytesAtAccounting':sum(p.stat().st_size for p in files),'reviewGifCount':len(list(OUT.rglob('*.gif'))),'note':'Wall span includes reuse/setup/evaluation and actual native renders, not a CPU-time estimate. Review artifacts assemble actual PNGs only. Complete transition rasters deliberately deferred until appearance is ready.'};(OUT/'resource-budget.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
